Cho hình vẽ sau. Biết $\widehat{O_{1}} =126^{\circ}$, tính số đo góc $\widehat{O_{2}}$.

\choice
{ $\widehat{O_{2} }=54^{\circ}$   }
   { $\widehat{O_{2} }=136^{\circ}$   }
     { \True $\widehat{O_{2} }=126^{\circ} $  }
    { $\widehat{O_{2} }=116^{\circ}$   }
}{
\begin{tikzpicture}
            % Vẽ các điểm A, B, C, D
            \coordinate (A) at (0, 0);
            \coordinate (B) at (4, 4);
            \coordinate (C) at (6, 0);
            \coordinate (D) at (2, -3);

            % Vẽ đường thẳng đi qua A và C
            \draw[thick] (A) -- (C);

            % Vẽ đường thẳng đi qua B và D
            \draw[thick] (B) -- (D) ;

            % Tìm giao điểm O của 2 đường thẳng
            \coordinate (O) at (intersection of A--C and B--D);

            % Đánh dấu các điểm A, B, C, D, O

            \fill (O) circle (2pt) node[above right] {O};
             \draw 
            (O) pic[draw,angle radius = 10] {{angle = B--O--A}} node[shift={{(-49:-15pt)}}]{{$1$}} 
            ;
             \draw 
            (O) pic[draw,angle radius = 10] {{angle = D--O--C}} node[shift={{(-45:14pt)}}]{{$2$}} 
            ;
        \end{tikzpicture}
}
\loigiai{
Vì $\widehat{O_{1} }$ và $\widehat{O_{2} }$ là hai góc đối đỉnh nên $\widehat{O_{2}}=\widehat{O_{1}} =126^{\circ}$
}\end{ex}

